function sourceSolutionHTML(q){
  const s=q.sourceSolution;if(!s)return "";
  const prefix="assets/pages/assessments/physics2/electromagnetism/solutions/";
  const pdfPrefix="assets/documents/assessments/physics2/electromagnetism-original-solution.pdf#page=";
  if(typeof s.image!=="string"||!s.image.startsWith(prefix)||s.image.includes("..")||!/^s[0-9]{2}\.png$/.test(s.image.slice(prefix.length)))return "";
  const pdf=typeof s.pdf==="string"&&s.pdf.startsWith(pdfPrefix)&&/^[0-9]+$/.test(s.pdf.slice(pdfPrefix.length))?s.pdf:"";
  return `<div class="source-solution-original"><h4>첨부 원문 해설</h4><p class="small muted">제공된 해설지의 해당 문항을 수정 없이 표시합니다. 아래 텍스트 풀이 및 원문 대조 메모와 함께 확인하세요.</p>${pdf?`<a class="source-link" target="_blank" rel="noopener" href="${YP.escapeHTML(pdf)}">원본 해설 PDF 해당 쪽 열기</a>`:""}<img src="${YP.escapeHTML(s.image)}" alt="${YP.escapeHTML(s.label||"원문 해설")}" loading="lazy" style="max-width:100%;height:auto;display:block"></div>`;
}
